package main

import (
	"strings"
	"testing"
	"time"
)

func TestTransformGCode(t *testing.T) {
	input := strings.Join([]string{
		"; HEADER_BLOCK_START",
		"; generated by OrcaSlicer 2.5.2",
		"; THUMBNAIL_BLOCK_START",
		"; fakebase64",
		"; THUMBNAIL_BLOCK_END",
		"; EXECUTABLE_BLOCK_START",
		"M73 P0 R10",
		";TYPE:Custom",
		"M82 ;absolute extrusion mode",
		";Header Start",
		"",
		";FLAVOR:Marlin",
		";header_type: 3dp,0.3mm",
		";material_type: PLA",
		";nozzle_temperature(°C): 220",
		";build_plate_temperature(°C): 60",
		"",
		";Header End",
		"",
		";G-code for 3dp engraving",
		";Generated by IVI 3licer",
		";Start GCode begin",
		"M104 S220",
		"M140 S60",
		"G28 ;home",
		"G1 Y-100.0 Z15.0 F2000",
		";Start GCode end",
		"M73 P5 R9",
		"G1 X-10.5 Y5.25 Z0.2 F1200",
		"G1 X12.5 Y-8.0 Z1.4 E2.1",
		"M104 S0",
		"; filament used [mm] = 3120.00",
		"; estimated printing time (normal mode) = 2h 16m 12s",
		"; layer_height = 0.15",
	}, "\n")

	now := time.Date(2026, 11, 21, 18, 0, 0, 0, time.UTC)
	out, meta, err := TransformGCode([]byte(input), now)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if !meta.Transformed {
		t.Fatalf("expected Transformed=true")
	}
	if meta.StrippedM73 != 1 {
		t.Fatalf("expected StrippedM73=1 (body M73), got %d", meta.StrippedM73)
	}
	if meta.NozzleTemp != "220" || meta.BedTemp != "60" || meta.Material != "PLA" {
		t.Fatalf("unexpected temps/material: %+v", meta)
	}
	if meta.MinX != -10.5 || meta.MaxX != 12.5 || meta.MinY != -8.0 || meta.MaxY != 5.25 || meta.MinZ != 0.2 || meta.MaxZ != 1.4 {
		t.Fatalf("unexpected bounds: %+v", meta)
	}

	got := string(out)
	if !strings.HasPrefix(got, ";Header Start\n") {
		t.Fatalf("expected output to start with ;Header Start, got:\n%s", got[:min(120, len(got))])
	}
	if strings.Contains(got, "M73 ") {
		t.Fatalf("expected all M73 commands stripped")
	}
	if !strings.Contains(got, "M82 ;absolute extrusion mode\n;Start GCode begin") {
		t.Fatalf("expected M82 immediately before ;Start GCode begin")
	}
	if !strings.Contains(got, ";TIME:8172\n") {
		t.Fatalf("expected ;TIME:8172, got:\n%s", got[:min(350, len(got))])
	}
	if !strings.Contains(got, ";estimated_time(s): 8172.00\n") {
		t.Fatalf("expected ;estimated_time(s): 8172.00, got:\n%s", got[:min(450, len(got))])
	}
	if !strings.Contains(got, ";Layer height: 0.15\n") {
		t.Fatalf("expected ;Layer height: 0.15")
	}
	if !strings.Contains(got, ";Filament used: 3.12m\n") {
		t.Fatalf("expected ;Filament used: 3.12m")
	}

	// Idempotency: running TransformGCode a second time should be a no-op.
	out2, meta2, err := TransformGCode(out, now)
	if err != nil {
		t.Fatalf("second transform error: %v", err)
	}
	if meta2.Transformed || !meta2.AlreadyReady {
		t.Fatalf("expected second run to be AlreadyReady=true, Transformed=false: %+v", meta2)
	}
	if string(out2) != got {
		t.Fatalf("expected idempotent output on second transform")
	}
}

func TestEnsureStartReprime(t *testing.T) {
	balanced := []string{
		";Start GCode begin",
		"G1 Z0.8 F500.0",
		"G1 E7.0 F300 ;re-prime 6.5mm end-of-print retraction + 0.5mm pressure",
		"G92 E0",
		"G1 X8.66 Y-98.94 E8.0 F500.0 ; intro line",
		";Start GCode end",
		";End GCode begin",
		"G91",
		"G1 E-6.5 F2400",
		";End of Gcode",
	}
	got, w := ensureStartReprime(balanced)
	if len(w) != 0 || len(got) != len(balanced) {
		t.Fatalf("expected balanced start/end prime untouched, got len=%d warnings=%v", len(got), w)
	}

	missingPrime := []string{
		";Start GCode begin",
		"G1 Z0.8 F500.0",
		"G1 X8.66 Y-98.94 E8.0 F500.0 ; intro line",
		";Start GCode end",
		";End GCode begin",
		"G91",
		"G1 E-6.5 F2400",
		";End of Gcode",
	}
	healed, w := ensureStartReprime(missingPrime)
	if len(w) != 1 || !strings.Contains(w[0], "AUTO-HEALED") {
		t.Fatalf("expected AUTO-HEALED notice, got %v", w)
	}
	if len(healed) != len(missingPrime)+2 || !strings.HasPrefix(healed[2], "G1 E7.0 F120") || healed[3] != "G92 E0" {
		t.Fatalf("expected G1 E7.0 F120 + G92 E0 injected before intro line, got %v", healed)
	}
}
